1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: grid;
13	    place-items: center;
14	    background: #eef0f3;
15	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16	  }
17	  .calc {
18	    width: min(320px, 100vw - 32px);
19	    padding: 16px;
20	    border-radius: 20px;
21	    background: #1f2329;
22	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
23	  }
24	  .display {
25	    height: 80px;
26	    margin-bottom: 16px;
27	    padding: 0 12px;
28	    border-radius: 12px;
29	    background: #111418;
30	    color: #fff;
31	    font-size: 40px;
32	    display: flex;
33	    align-items: center;
34	    justify-content: flex-end;
35	    overflow: hidden;
36	    white-space: nowrap;
37	    font-variant-numeric: tabular-nums;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 10px;
43	  }
44	  button {
45	    height: 60px;
46	    border: 0;
47	    border-radius: 12px;
48	    background: #3a4049;
49	    color: #fff;
50	    font: inherit;
51	    font-size: 22px;
52	    cursor: pointer;
53	  }
54	  button:hover { filter: brightness(1.15); }
55	  button:active { filter: brightness(0.9); }
56	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
57	  .op { background: #f08c2e; }
58	  .op.active { background: #fff; color: #f08c2e; }
59	  .fn { background: #8a929c; color: #111; }
60	  .wide { grid-column: span 2; }
61	</style>
62	</head>
63	<body>
64	<main class="calc">
65	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
66	  <div class="keys">
67	    <button class="fn" data-testid="key-clear" data-key="clear">AC</button>
68	    <button class="fn" data-testid="key-sign" data-key="sign" aria-label="change sign">±</button>
69	    <button class="fn" data-testid="key-percent" data-key="percent" aria-label="percent">%</button>
70	    <button class="op" data-testid="key-div" data-key="div" aria-label="divide">÷</button>
71	    <button data-testid="key-7" data-key="7">7</button>
72	    <button data-testid="key-8" data-key="8">8</button>
73	    <button data-testid="key-9" data-key="9">9</button>
74	    <button class="op" data-testid="key-mul" data-key="mul" aria-label="multiply">×</button>
75	    <button class="op" data-testid="key-sub" data-key="sub" aria-label="subtract">−</button>
76	    <button data-testid="key-4" data-key="4">4</button>
77	    <button data-testid="key-5" data-key="5">5</button>
78	    <button data-testid="key-6" data-key="6">6</button>
79	    <button class="op" data-testid="key-add" data-key="add" aria-label="add">+</button>
80	    <button data-testid="key-1" data-key="1">1</button>
81	    <button data-testid="key-2" data-key="2">2</button>
82	    <button data-testid="key-3" data-key="3">3</button>
83	    <button class="wide" data-testid="key-0" data-key="0">0</button>
84	    <button data-testid="key-dot" data-key="dot" aria-label="decimal point">.</button>
85	    <button class="op" data-testid="key-equals" data-key="equals" aria-label="equals">=</button>
86	  </div>
87	</main>
88	<script>
89	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
90	// entry (digits being typed, or null), value (the current number, never rounded),
91	// error (true after a division by zero; only clear leaves it).
92	var OPS = {
93	  add: function (a, b) { return a + b; },
94	  sub: function (a, b) { return a - b; },
95	  mul: function (a, b) { return a * b; },
96	  div: function (a, b) { return a / b; }
97	};
98	
99	function initialState() {
100	  return { acc: null, op: null, entry: null, value: 0, error: false };
101	}
102	
103	function errorState(v) {
104	  return { acc: null, op: null, entry: null, value: v, error: true };
105	}
106	
107	function press(s, key) {
108	  if (key === 'clear') return initialState();
109	
110	  // In the error state every key except clear is ignored.
111	  if (s.error) return s;
112	
113	  if (/^[0-9]$/.test(key)) {
114	    var entry = s.entry === null || s.entry === '0' ? key : s.entry === '-0' ? '-' + key : s.entry + key;
115	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false };
116	  }
117	
118	  if (key === 'dot') {
119	    var e = s.entry === null ? '0' : s.entry;
120	    if (e.indexOf('.') !== -1) return s;
121	    e += '.';
122	    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false };
123	  }
124	
125	  // Sign and percent act on the current entry. Right after an operator there is no
126	  // entry yet, so they start one from 0. After a result they act on the value.
127	  if (key === 'sign' || key === 'percent') {
128	    if (s.entry === null && !s.op) {
129	      var nv = key === 'sign' ? -s.value : s.value / 100;
130	      return { acc: null, op: null, entry: null, value: nv, error: false };
131	    }
132	    var cur = s.entry === null ? '0' : s.entry;
133	    var ne = key === 'sign' ? (cur[0] === '-' ? cur.slice(1) : '-' + cur) : shiftDecimal(cur, -2);
134	    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false };
135	  }
136	
137	  if (key in OPS) {
138	    // Operator right after another operator replaces it.
139	    if (s.op && s.entry === null) return { acc: s.acc, op: key, entry: null, value: s.value, error: false };
140	    // Immediate execution: finish the waiting operation first, strictly left to right,
141	    // no precedence. The display always shows a real running result.
142	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
143	    if (!isFinite(v)) return errorState(v);
144	    return { acc: v, op: key, entry: null, value: v, error: false };
145	  }
146	
147	  if (key === 'equals') {
148	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false };
149	    var r = OPS[s.op](s.acc, s.value);
150	    if (!isFinite(r)) return errorState(r);
151	    return { acc: null, op: null, entry: null, value: r, error: false };
152	  }
153	
154	  return s;
155	}
156	
157	// Moves the decimal point of an entry string by n places, exactly, with no float noise.
158	// shiftDecimal('50', -2) is '0.5'.
159	function shiftDecimal(entry, n) {
160	  var sign = entry[0] === '-' ? '-' : '';
161	  var parts = entry.slice(sign.length).split('.');
162	  var digits = parts[0] + (parts[1] || '');
163	  var pos = parts[0].length + n;
164	  var str = pos <= 0 ? '0.' + '0'.repeat(-pos) + digits
165	    : pos >= digits.length ? digits + '0'.repeat(pos - digits.length)
166	    : digits.slice(0, pos) + '.' + digits.slice(pos);
167	  if (str.indexOf('.') !== -1) str = str.replace(/0+$/, '').replace(/\.$/, '');
168	  str = str.replace(/^0+(?=\d)/, '');
169	  return sign + str;
170	}
171	
172	// Presentation only: at most 10 significant digits, no trailing zeros, no separators.
173	// Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
174	function formatNumber(x) {
175	  var m = Math.abs(x).toExponential(9).split('e');
176	  var digits = m[0].replace('.', '');
177	  var exp = Number(m[1]);
178	  var sign = x < 0 ? '-' : '';
179	  if (x !== 0 && (exp >= 10 || exp < -9)) {
180	    return sign + m[0].replace(/\.?0+$/, '') + 'e' + m[1];
181	  }
182	  var int = exp >= 0 ? digits.slice(0, exp + 1) : '0';
183	  var frac = (exp >= 0 ? digits.slice(exp + 1) : '0'.repeat(-exp - 1) + digits).replace(/0+$/, '');
184	  return (int === '0' && frac === '' ? '' : sign) + int + (frac ? '.' + frac : '');
185	}
186	
187	// Visible text: the entry exactly as typed, Error, or the value formatted at render time.
188	function displayText(s) {
189	  if (s.error) return 'Error';
190	  if (s.entry !== null) return s.entry;
191	  return formatNumber(s.value);
192	}
193	
194	if (typeof document !== 'undefined') {
195	  var state = initialState();
196	  var display = document.querySelector('[data-testid="calc-display"]');
197	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
198	
199	  function render() {
200	    display.textContent = displayText(state);
201	    display.setAttribute('data-value', String(state.value));
202	    display.setAttribute('data-error', state.error ? 'true' : 'false');
203	    for (var i = 0; i < opButtons.length; i++) {
204	      var b = opButtons[i];
205	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null);
206	    }
207	  }
208	
209	  document.querySelector('.keys').addEventListener('click', function (ev) {
210	    var btn = ev.target.closest('button');
211	    if (!btn) return;
212	    state = press(state, btn.dataset.key);
213	    render();
214	  });
215	
216	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
217	    '%': 'percent', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
218	  document.addEventListener('keydown', function (ev) {
219	    var key = /^[0-9]$/.test(ev.key) ? ev.key : KEYMAP[ev.key];
220	    if (!key || ev.ctrlKey || ev.metaKey || ev.altKey) return;
221	    ev.preventDefault();
222	    state = press(state, key);
223	    render();
224	  });
225	
226	  render();
227	}
228	</script>
229	</body>
230	</html>
