def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''    <button class="fn" data-testid="key-clear"''','''    <button class="fn wide" data-testid="key-lparen" data-key="lparen" aria-label="open group">(</button>
    <button class="fn wide" data-testid="key-rparen" data-key="rparen" aria-label="close group">)</button>
    <button class="fn" data-testid="key-clear"''')
rep('''// error (true after a division by zero; only clear leaves it).''','''// error (true after a division by zero; only clear leaves it), stack (saved acc/op of each
// open group), closed (true right after `)`: value is a finished group result, not an entry).''')
rep('''  return { acc: null, op: null, entry: null, value: 0, error: false };''','''  return { acc: null, op: null, entry: null, value: 0, error: false, stack: [], closed: false };''')
rep('''  return { acc: null, op: null, entry: null, value: v, error: true };''','''  return { acc: null, op: null, entry: null, value: v, error: true, stack: [], closed: false };''')
rep('''    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false };''','''    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false, stack: s.stack, closed: false };''')
rep('''    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false };''','''    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false, stack: s.stack, closed: false };''')
rep('''  // entry yet, so they start one from 0. After a result they act on the value.
  if (key === 'sign' || key === 'percent') {
    if (s.entry === null && !s.op) {
      var nv = key === 'sign' ? -s.value : s.value / 100;
      return { acc: null, op: null, entry: null, value: nv, error: false };
    }''','''  // entry yet, so they start one from 0. After a result or a closed group they act on the value.
  if (key === 'sign' || key === 'percent') {
    if (s.entry === null && (!s.op || s.closed)) {
      var nv = key === 'sign' ? -s.value : s.value / 100;
      return { acc: s.acc, op: s.op, entry: null, value: nv, error: false, stack: s.stack, closed: s.closed };
    }''')
rep('''    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false };''','''    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false, stack: s.stack, closed: false };''')
rep('''    if (s.op && s.entry === null) return { acc: s.acc, op: key, entry: null, value: s.value, error: false };''','''    if (s.op && s.entry === null && !s.closed) return { acc: s.acc, op: key, entry: null, value: s.value, error: false, stack: s.stack, closed: false };''')
rep('''    return { acc: v, op: key, entry: null, value: v, error: false };
  }
''','''    return { acc: v, op: key, entry: null, value: v, error: false, stack: s.stack, closed: false };
  }

  // `(` saves the waiting operation and starts a fresh one inside the group. It only
  // makes sense where a number could start, so it is ignored after an entry or a group.
  if (key === 'lparen') {
    if (s.entry !== null || s.closed) return s;
    var frame = { acc: s.acc, op: s.op };
    return { acc: null, op: null, entry: null, value: 0, error: false, stack: s.stack.concat([frame]), closed: false };
  }

  // `)` finishes the group like equals, then restores the saved operation with the group
  // result as its right operand. Without an open group it is ignored.
  if (key === 'rparen') {
    if (!s.stack.length) return s;
    var g = s.op ? OPS[s.op](s.acc, s.value) : s.value;
    if (!isFinite(g)) return errorState(g);
    var top = s.stack[s.stack.length - 1];
    return { acc: top.acc, op: top.op, entry: null, value: g, error: false, stack: s.stack.slice(0, -1), closed: true };
  }
''')
rep('''  if (key === 'equals') {
    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false };''','''  if (key === 'equals') {
    // Equals closes any groups left open.
    while (s.stack.length) {
      s = press(s, 'rparen');
      if (s.error) return s;
    }
    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false, stack: [], closed: false };''')
rep('''    return { acc: null, op: null, entry: null, value: r, error: false };''','''    return { acc: null, op: null, entry: null, value: r, error: false, stack: [], closed: false };''')
rep('''state.op === b.dataset.key && state.entry === null);''','''state.op === b.dataset.key && state.entry === null && !state.closed);''')
rep("""'%': 'percent',""","""'%': 'percent', '(': 'lparen', ')': 'rparen',""")
open(p,'w').write(s)
